async ivSaveConfig() {
  try { await Kav1.put("inviters/config", { key: this.iv.key, require: !!this.iv.require }); this.ivSay("נשמר", false); await this.ivLoad(); }
  catch (e) { this.ivSay(e.message, true); }
},
async ivAdd() {
  if (!(this.iv.newName || "").trim()) return;
  try { await Kav1.post("inviters", { name: this.iv.newName }); this.iv.newName = ""; this.ivSay("נוסף לרשימה", false); await this.ivLoad(); }
  catch (e) { this.ivSay(e.message, true); }
},
async ivRename(i) {
  const rewrite = confirm("לעדכן את השם גם אצל המבקרים שרשומים עם השם הקודם? (אישור: כן, עם גיבוי לפני. ביטול: רק ברשימה)");
  try { const r = await Kav1.put("inviters/" + i.id, { name: i.name, rename_visitors: rewrite }); this.ivSay("נשמר" + (r.backup ? ". גיבוי: " + r.backup : ""), false); await this.ivLoad(); }
  catch (e) { this.ivSay(e.message, true); await this.ivLoad(); }
},
async ivToggle(i) {
  try { await Kav1.put("inviters/" + i.id, { active: !i.active }); await this.ivLoad(); }
  catch (e) { this.ivSay(e.message, true); }
},
async ivDelete(i) {
  if (!confirm("להסיר את " + i.name + " מהרשימה? המבקרים לא נמחקים ושמם נשמר אצלם.")) return;
  try { await Kav1.del("inviters/" + i.id); this.ivSay("הוסר מהרשימה", false); await this.ivLoad(); }
  catch (e) { this.ivSay(e.message, true); }
},
async ivPreview() {
  try { this.iv.preview = await Kav1.get("inviters/migration/preview"); this.ivSay("", false); }
  catch (e) { this.ivSay(e.message, true); }
},
async ivApply(rewrite) {
  if (rewrite && !confirm("לאחד איות אצל המבקרים? נשמר גיבוי מאומת לפני, ושום מבקר לא נמחק.")) return;
  try {
    const r = await Kav1.post("inviters/migration/apply", { rewrite });
    this.ivSay("נוספו " + r.added + " לרשימה" + (rewrite ? ", עודכנו " + r.rewritten + " מבקרים" : "") + (r.backup ? ". גיבוי: " + r.backup : ""), false);
    await this.ivLoad(); await this.ivPreview();
  } catch (e) { this.ivSay(e.message, true); }
},

